<script setup lang="ts">import {ref,computed,watch} from 'vue';import type {Workspace} from '../stores/workspace';import type {DatasetRevision} from '../types/domain';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';import {create,updateObservations,revisions} from '../api/datasets';import {useAsync} from '../hooks/useAsync';import {PERIODS} from '../constants/enums';const props=defineProps<{data:Workspace;canWrite:boolean;refresh:()=>Promise<void>}>();const selected=ref(''),name=ref(''),source=ref('intake_observations.json'),text=ref(''),batchText=ref('');const history=ref<DatasetRevision[]>([]);const dataset=computed(()=>props.data.datasets.find(d=>d.id===selected.value)||props.data.datasets[0]);const {busy,error,execute}=useAsync();const batch=useAsync();async function submit(){await execute(async()=>{await create({name:name.value,source:source.value,rows:JSON.parse(text.value)});name.value='';text.value='';await props.refresh()})}async function submitBatch(){if(!dataset.value)return;await batch.execute(async()=>{await updateObservations(dataset.value.id,{changes:JSON.parse(batchText.value)});batchText.value='';await props.refresh();await loadHistory()})}async function loadHistory(){if(dataset.value)history.value=await revisions(dataset.value.id)}watch(()=>dataset.value?.id,()=>{loadHistory().catch(()=>{history.value=[]})},{immediate:true});
</script><template><PageHeading code="02 / INTAKE OBSERVATIONS" title="把等候，拆回到达与服务。" description="每条记录保留匿名样本编号、时段、到达间隔与服务时长。补录、更正与撤回按样本编号成批提交，同批有错则整批不生效。"/><section class="paper"><div class="section-heading"><h2>时长观测簿</h2><select aria-label="选择观测集" :value="dataset?.id" @change="selected=($event.target as HTMLSelectElement).value"><option v-for="d in data.datasets" :key="d.id" :value="d.id">{{d.name}}</option></select></div><template v-if="dataset"><div class="data-caption"><b>{{dataset.rows.length}}条观测</b><span>版本 r{{dataset.revision}}</span><span>{{dataset.source}}</span><span>无真实个人信息</span></div><div class="table-scroll"><table><thead><tr><th>匿名样本</th><th>时段</th><th>到达间隔 / 分钟</th><th>服务时长 / 分钟</th></tr></thead><tbody><tr v-for="r in dataset.rows.slice(0,40)" :key="r.sample_id"><td>{{r.sample_id}}</td><td>{{PERIODS[r.period]}}</td><td>{{r.interarrival_minutes.toFixed(3)}}</td><td>{{r.service_minutes.toFixed(3)}}</td></tr></tbody></table></div><p class="caption">预览前40条，剖面估计使用所选时段的全部观测。</p></template><Notice v-else>请先导入至少20条时长观测，再创建服务剖面。</Notice></section><section v-if="canWrite&&dataset" class="paper"><h2>按样本编号批量更新</h2><p class="caption">upsert 用于补录新编号或更正已有编号，withdraw 用于撤回。任一条校验失败，整批不生效；生效后关联剖面自动重算，未运行方案将标记失效。</p><form class="grid-form" @submit.prevent="submitBatch"><label class="wide">变更JSON<textarea rows="4" required v-model="batchText" placeholder='[{"action":"upsert","sample_id":"YX-0001","period":"peak","interarrival_minutes":3.8,"service_minutes":11.5},{"action":"withdraw","sample_id":"YX-0002"}]'/></label><Notice v-if="batch.error.value" error>{{batch.error.value}}</Notice><button :disabled="batch.busy.value">校验并整批生效</button></form></section><section v-if="dataset&&history.length" class="paper"><h2>版本沿革</h2><div class="table-scroll"><table><thead><tr><th>版本</th><th>补录</th><th>更正</th><th>撤回</th><th>校验码</th><th>操作者</th><th>时间</th></tr></thead><tbody><tr v-for="v in history" :key="v.id"><td>r{{v.revision}}</td><td>{{v.added}}</td><td>{{v.corrected}}</td><td>{{v.withdrawn}}</td><td>{{v.checksum.slice(0,16)}}</td><td>{{v.actor}}</td><td>{{v.created_at.slice(0,19).replace('T',' ')}}</td></tr></tbody></table></div></section><section v-if="canWrite" class="paper"><h2>导入匿名时长观测</h2><form class="grid-form" @submit.prevent="submit"><label>观测集名称<input required minlength="2" v-model="name"/></label><label>来源文件名<input v-model="source"/></label><label class="wide">JSON数组<textarea rows="4" required v-model="text" placeholder='[{"sample_id":"YX-01","period":"peak","interarrival_minutes":4,"service_minutes":12}, …]'/></label><Notice v-if="error" error>{{error}}</Notice><button :disabled="busy">核查并导入</button></form></section></template>
